func (q *Queries) ListWatchedTasks(ctx context.Context, keys []string) ([]*ListWatchedTasksRow, error) {
	rows, err := q.db.Query(ctx, listWatchedTasks, keys)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListWatchedTasksRow
	for rows.Next() {
		var i ListWatchedTasksRow
		if err := rows.Scan(
			&i.Task.ID,
			&i.Task.WorkflowID,
			&i.Task.Slug,
			&i.Task.Title,
			&i.Task.Goal,
			&i.Task.ArchivedAt,
			&i.Task.CreatedAt,
			&i.Task.UpdatedAt,
			&i.Task.EngineID,
			&i.Task.Cwd,
			&i.Task.Branch,
			&i.Task.AdoptedBranch,
			&i.Task.ProvisionEnabled,
			&i.Task.WorktreeRemoved,
			&i.Task.RepositoryUrl,
			&i.Task.HeadSha,
			&i.Task.LastRebase,
			&i.Task.Sequence,
			&i.Task.LinesAdded,
			&i.Task.LinesRemoved,
			&i.Task.MovedSinceRound,
			&i.Task.DeletingAt,
			&i.Task.CleaningAt,
			&i.Task.FailureReason,
			&i.Task.Notes,
			&i.Task.NotesUpdatedAt,
			&i.Task.IsHidden,
			&i.FailedRun,
			&i.Documents,
			&i.DocumentsUpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listWorkflowTaskIDs = `-- name: ListWorkflowTaskIDs :many
SELECT
    id
FROM
    tasks
WHERE
    workflow_id = $1
ORDER BY
    id
`

func (q *Queries) ListWorkflowTaskIDs(ctx context.Context, workflowID string) ([]string, error) {
	rows, err := q.db.Query(ctx, listWorkflowTaskIDs, workflowID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

