const updateTask = `-- name: UpdateTask :one
UPDATE
    tasks
SET
    slug = COALESCE($1, slug),
    title = COALESCE($2, title),
    goal = COALESCE($3, goal),
    notes = COALESCE($4, notes),
    notes_updated_at = CASE WHEN $4::text IS NULL THEN
        notes_updated_at
    ELSE
        NOW()
    END
WHERE
    id = $5
    AND deleting_at IS NULL
    AND ($4::text IS NULL
        OR notes_updated_at IS NOT DISTINCT FROM $6::timestamptz)
RETURNING
    id, workflow_id, slug, title, goal, archived_at, created_at, updated_at, engine_id, cwd, branch, adopted_branch, provision_enabled, worktree_removed, repository_url, head_sha, last_rebase, sequence, lines_added, lines_removed, moved_since_round, deleting_at, cleaning_at, failure_reason, notes, notes_updated_at, is_hidden
`

type UpdateTaskParams struct {
	Slug               *string
	Title              *string
	Goal               *string
	Notes              *string
	ID                 string
	ReadNotesUpdatedAt *time.Time
}

func (q *Queries) UpdateTask(ctx context.Context, arg UpdateTaskParams) (*Task, error) {
	row := q.db.QueryRow(ctx, updateTask,
		arg.Slug,
		arg.Title,
		arg.Goal,
		arg.Notes,
		arg.ID,
		arg.ReadNotesUpdatedAt,
	)
	var i Task
	err := row.Scan(
		&i.ID,
		&i.WorkflowID,
		&i.Slug,
		&i.Title,
		&i.Goal,
		&i.ArchivedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.EngineID,
		&i.Cwd,
		&i.Branch,
		&i.AdoptedBranch,
		&i.ProvisionEnabled,
		&i.WorktreeRemoved,
		&i.RepositoryUrl,
		&i.HeadSha,
		&i.LastRebase,
		&i.Sequence,
		&i.LinesAdded,
		&i.LinesRemoved,
		&i.MovedSinceRound,
		&i.DeletingAt,
		&i.CleaningAt,
		&i.FailureReason,
		&i.Notes,
		&i.NotesUpdatedAt,
		&i.IsHidden,
	)
	return &i, err
}
